import{_ as t,o as r,c as a,ah as n}from"./chunks/framework.C-FRNfAJ.js";const g=JSON.parse('{"title":"Facturation","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"guide/coordinateur/facturation.md","filePath":"src/guide/coordinateur/facturation.md"}'),s={name:"guide/coordinateur/facturation.md"};function o(i,e,u,l,c,d){return r(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="facturation" tabindex="-1">Facturation <a class="header-anchor" href="#facturation" aria-label="Permalink to &quot;Facturation&quot;">​</a></h1><p><strong>Finance → Facturation</strong> rassemble les factures, les paiements, les relances et les avoirs. Kura <strong>n&#39;encaisse rien</strong> : les paiements arrivent hors de Kura, et vous les y enregistrez.</p><h2 id="les-factures" tabindex="-1">Les factures <a class="header-anchor" href="#les-factures" aria-label="Permalink to &quot;Les factures&quot;">​</a></h2><p>Chaque inscription donne trois factures, aux dates calculées par la cohorte : signature (30 %), mi-parcours (40 %), solde (30 %). Elles sont <strong>émises au fil de l&#39;eau</strong> : la première à la contre-signature de la convention, les autres <strong>15 jours avant leur échéance</strong>. La référence est <code>FAC-NB-AAAA-XXX</code> ; le PDF part par e-mail au payeur.</p><p>Les montants sont <strong>hors taxe</strong> : la facture porte la mention d&#39;exonération et les modalités de paiement, que l&#39;Administrateur règle.</p><p>En financement partagé, chaque tranche donne <strong>une facture par payeur</strong>, suivie séparément. La page liste aussi les factures des événements payants, des devis entreprise et des mises en relation.</p><p>La liste se filtre par statut (<strong>Émises</strong>, <strong>En retard</strong>, <strong>Payées</strong>, <strong>Annulées</strong>) et se recherche par référence, payeur ou apprenant.</p><h2 id="enregistrer-un-paiement" tabindex="-1">Enregistrer un paiement <a class="header-anchor" href="#enregistrer-un-paiement" aria-label="Permalink to &quot;Enregistrer un paiement&quot;">​</a></h2><p>Sur une facture, <strong>Paiement</strong> demande :</p><ul><li>le <strong>montant reçu</strong> (en FCFA), qui ne peut jamais dépasser le reste dû ;</li><li>le <strong>moyen de paiement</strong> : virement, chèque, Mobile Money, carte bancaire ou espèces ;</li><li>la <strong>référence</strong> de la transaction ;</li><li>la <strong>date</strong> de réception.</li></ul><p>Un paiement <strong>partiel</strong> est possible. Le payeur reçoit un accusé. Quand le solde de la facture est atteint, elle passe « Payée ».</p><p><strong>Payer rétablit l&#39;accès</strong> : un compte suspendu pour impayé est réactivé automatiquement, dans Kura et dans Sève.</p><h2 id="relancer" tabindex="-1">Relancer <a class="header-anchor" href="#relancer" aria-label="Permalink to &quot;Relancer&quot;">​</a></h2><p>Kura envoie seul les rappels avant l&#39;échéance (J-15, J-7, J-1) et le lendemain (J+1). <strong>La relance de J+7 est la vôtre</strong> : le filtre <strong>À relancer (J+7)</strong> liste les factures concernées. Contactez l&#39;apprenant ou le financeur par e-mail ou par téléphone, puis cliquez sur <strong>Relance faite</strong> : la date est conservée.</p><table tabindex="0"><thead><tr><th>Moment</th><th>Qui agit</th></tr></thead><tbody><tr><td>J+1</td><td>Kura : rappel</td></tr><tr><td>J+7</td><td><strong>Vous</strong> : relance personnalisée</td></tr><tr><td>J+15</td><td>Kura : la facture passe « En retard », moratoire automatique de 15 jours</td></tr><tr><td>J+30</td><td>Kura : suspension de l&#39;accès à Sève</td></tr><tr><td>Après J+30</td><td><strong>Vous</strong> : entretien, plan de régularisation éventuel, sinon désinscription</td></tr></tbody></table><p>Le moratoire est <strong>unique</strong> et non renégociable. Quand le payeur en retard est le <strong>financeur</strong>, l&#39;apprenant est suspendu aussi. Pour les cohortes dédiées d&#39;une entreprise, la suspension porte sur les inscriptions de la cohorte, pas sur les comptes.</p><h2 id="si-une-cohorte-change-ou-est-annulee" tabindex="-1">Si une cohorte change ou est annulée <a class="header-anchor" href="#si-une-cohorte-change-ou-est-annulee" aria-label="Permalink to &quot;Si une cohorte change ou est annulée&quot;">​</a></h2><ul><li><strong>Changement de cohorte.</strong> Les paiements sont conservés ; le reste dû des factures déjà émises est annulé par un <strong>avoir d&#39;annulation</strong> (<code>AV-NB-AAAA-XXX</code>). La nouvelle convention refacture chaque tranche en déduisant ce que le payeur a déjà réglé.</li><li><strong>Annulation par NextBoxx.</strong> Kura émet un <strong>avoir de remboursement</strong> de 100 % des sommes payées. Il apparaît « À rembourser » dans <strong>Avoirs</strong> : une fois le remboursement effectué, cliquez sur <strong>Remboursement fait</strong> et indiquez la date.</li><li><strong>Abandon.</strong> Pas d&#39;avoir : voir <a href="./inscriptions.html#enregistrer-un-abandon">Inscriptions</a>.</li></ul><h2 id="ce-qui-est-facture" tabindex="-1">Ce qui est facturé <a class="header-anchor" href="#ce-qui-est-facture" aria-label="Permalink to &quot;Ce qui est facturé&quot;">​</a></h2><p>Seuls certains événements déclenchent une facture : les échéances de l&#39;échéancier, l&#39;inscription à un événement payant, un devis entreprise accepté, une mise en relation confirmée.</p>',20)])])}const m=t(s,[["render",o]]);export{g as __pageData,m as default};
